        "text": "일제 강점기는 라디오와 축음기가 보급되면서 대중가요가 확산된 시기였습니다. 우리 오케스트라에서는 당시 발매되었던 대중가요를 관현악으로 편곡한 공연을 준비하였습니다. 식민지 시기를 살아간 우리 민족의 다양한 감정을 느낄 수 있는 자리에 여러분을 초대합니다."
